css:
.controlnum-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #d8e2ef;
    background: radial-gradient(circle at 18% 0%, #14233a 0%, #0d1726 55%, #0a1119 100%);
    border-radius: 18px;
}

.controlnum-container * {
    box-sizing: border-box;
}

.controlnum-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0b1f33 0%, #123a52 55%, #0e5d63 100%);
    color: #eaf6ff;
    border-radius: 16px;
    margin-bottom: 18px;
    border: 1px solid rgba(56, 209, 196, 0.18);
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45);
}

.controlnum-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.controlnum-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #ffd27a;
    background: rgba(255, 210, 122, 0.12);
    border: 1px solid rgba(255, 210, 122, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.controlnum-subtitle {
    margin: 12px auto 0;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #bcd4e6;
}

.controlnum-mandate {
    display: flex;
    align-items: stretch;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 18px;
}

.controlnum-mandate-firm,
.controlnum-mandate-target {
    flex: 1;
    background: #11203353;
    background: rgba(20, 35, 56, 0.65);
    border: 1px solid rgba(86, 120, 158, 0.30);
    border-radius: 14px;
    padding: 14px 18px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.controlnum-mandate-target {
    border-left: 5px solid #38d1c4;
    align-items: flex-end;
    text-align: right;
}

.controlnum-mandate-firm {
    border-left: 5px solid #ffd27a;
}

.controlnum-firm-name,
.controlnum-mandate-value {
    font-weight: 800;
    font-size: 1.05rem;
    color: #eaf6ff;
}

.controlnum-mandate-value {
    color: #38d1c4;
    font-variant-numeric: tabular-nums;
}

.controlnum-firm-meta,
.controlnum-mandate-label {
    font-size: 0.8rem;
    color: #8aa3bd;
    line-height: 1.4;
}

.controlnum-mandate-label {
    text-transform: uppercase;
    letter-spacing: 0.8px;
    font-weight: 700;
    color: #6f8aa6;
}

.controlnum-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb6cd;
    margin-bottom: 16px;
    padding: 4px;
}

.controlnum-period-counter #currentDay,
.controlnum-period-counter #maxPeriods {
    font-weight: 800;
    color: #38d1c4;
}

.controlnum-round-name {
    background: rgba(56, 209, 196, 0.16);
    color: #5fe3d4;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.controlnum-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffd27a;
    background: rgba(255, 210, 122, 0.12);
    border: 1px solid rgba(255, 210, 122, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.controlnum-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.controlnum-status-card {
    background: linear-gradient(160deg, #16273d 0%, #101c2d 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid rgba(86, 120, 158, 0.22);
    border-top: 4px solid #38d1c4;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.35);
}

.controlnum-card-margin { border-top-color: #38d1c4; }
.controlnum-card-congruence { border-top-color: #4f9bff; }
.controlnum-card-clv { border-top-color: #9d7bff; }
.controlnum-card-budget { border-top-color: #ffd27a; }

.controlnum-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #7e96b0;
}

.controlnum-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #eaf6ff;
    font-variant-numeric: tabular-nums;
}

.controlnum-card-margin .controlnum-value { color: #38d1c4; }
.controlnum-card-congruence .controlnum-value { color: #4f9bff; }
.controlnum-card-clv .controlnum-value { color: #b69bff; }
.controlnum-card-budget .controlnum-value { color: #ffd27a; }

.controlnum-sublabel {
    font-size: 0.74rem;
    color: #7e96b0;
    line-height: 1.35;
}

/* Margin colour-story states (set by the adapter formatter). */
.controlnum-card-margin.controlnum-margin-loss { border-top-color: #ff6b6b; }
.controlnum-card-margin.controlnum-margin-loss .controlnum-value { color: #ff6b6b; }
.controlnum-card-margin.controlnum-margin-target { border-top-color: #46e3a0; }
.controlnum-card-margin.controlnum-margin-target .controlnum-value { color: #46e3a0; }

.controlnum-card-budget.controlnum-budget-empty .controlnum-value { color: #ff6b6b; }

.controlnum-leak-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: rgba(20, 35, 56, 0.65);
    border: 1px solid rgba(255, 107, 107, 0.30);
    color: #b6c8dc;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.controlnum-leak-bar #leakDisplay {
    font-size: 1.15rem;
    letter-spacing: 0.3px;
    color: #ff6b6b;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.controlnum-leak-bar.controlnum-leak-mid #leakDisplay { color: #ffd27a; }
.controlnum-leak-bar.controlnum-leak-low { border-color: rgba(70, 227, 160, 0.34); }
.controlnum-leak-bar.controlnum-leak-low #leakDisplay { color: #46e3a0; }

.controlnum-briefing {
    display: flex;
    gap: 14px;
    background: rgba(20, 35, 56, 0.55);
    border-left: 5px solid #38d1c4;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid rgba(86, 120, 158, 0.20);
    border-left: 5px solid #38d1c4;
}

.controlnum-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.controlnum-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #eaf6ff;
    margin-bottom: 6px;
}

.controlnum-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c4d6e8;
}

.controlnum-briefing-text strong { color: #5fe3d4; }
.controlnum-briefing-text em { color: #ffd27a; font-style: italic; }

.controlnum-controls {
    background: linear-gradient(160deg, #142336 0%, #0e1a29 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid rgba(86, 120, 158, 0.22);
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.32);
}

.controlnum-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eaf6ff;
    border-bottom: 2px solid rgba(86, 120, 158, 0.28);
    padding-bottom: 8px;
}

.controlnum-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #c4d6e8;
    margin: 14px 0 6px;
}

.controlnum-container select,
.controlnum-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2f4863;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0c1726;
    color: #eaf6ff;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.controlnum-container select:focus,
.controlnum-container input[type="number"]:focus {
    outline: none;
    border-color: #38d1c4;
    box-shadow: 0 0 0 3px rgba(56, 209, 196, 0.18);
}

.controlnum-container select option {
    background-color: #0c1726;
    color: #eaf6ff;
}

.controlnum-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #38d1c4;
}

.controlnum-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb6cd;
    margin-top: 4px;
}

.controlnum-range-readout span:nth-child(2) {
    color: #38d1c4;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.controlnum-hint {
    font-size: 0.8rem;
    color: #7e96b0;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.controlnum-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.controlnum-container .btn-primary {
    background: linear-gradient(135deg, #0e5d63 0%, #38d1c4 100%);
    border: none;
    color: #04202a;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 10px 22px rgba(56, 209, 196, 0.28);
}

.controlnum-container .btn-primary:hover {
    filter: brightness(1.08);
}

.controlnum-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2f4863;
    color: #9fb6cd;
    background: transparent;
}

.controlnum-container .btn-outline-secondary:hover {
    background: rgba(86, 120, 158, 0.14);
    color: #d8e2ef;
}

.controlnum-coach {
    background: linear-gradient(160deg, #0b1f33 0%, #0d2a30 100%);
    color: #d7ecef;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(56, 209, 196, 0.22);
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.34);
}

.controlnum-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd27a;
    margin-bottom: 8px;
}

.controlnum-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.controlnum-coach-body strong { color: #5fe3d4; }
.controlnum-coach-body em { color: #ffd27a; font-style: italic; }

.controlnum-history,
.controlnum-chart {
    background: linear-gradient(160deg, #142336 0%, #0e1a29 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(86, 120, 158, 0.22);
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.32);
}

.controlnum-history h3,
.controlnum-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eaf6ff;
}

.controlnum-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c4d6e8;
}

.controlnum-container table#usfHistoryTable th {
    background: rgba(56, 209, 196, 0.10);
    color: #5fe3d4;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid rgba(86, 120, 158, 0.34);
}

.controlnum-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(86, 120, 158, 0.16);
    color: #c4d6e8;
    font-variant-numeric: tabular-nums;
}

.controlnum-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(86, 120, 158, 0.06);
}

.controlnum-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .controlnum-container {
        padding: 14px;
    }
    .controlnum-header h1 {
        font-size: 1.7rem;
    }
    .controlnum-mandate {
        flex-direction: column;
    }
    .controlnum-mandate-target {
        align-items: flex-start;
        text-align: left;
    }
    .controlnum-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .controlnum-value {
        font-size: 2.05rem;
    }
    .controlnum-clock {
        margin-left: 0;
    }
    .controlnum-period-counter {
        font-size: 0.88rem;
    }
    .controlnum-leak-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .controlnum-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.cn-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.cn-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #8296b0; margin-bottom: 6px; }
.cn-cm-verdict { font-size: 22px; font-weight: 700; color: #eaf1f8; margin-bottom: 8px; }
.cn-cm-score { font-size: 16px; color: #eaf1f8; margin-bottom: 16px; }
.cn-cm-score strong { color: #38d1c4; }
.cn-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #8296b0; margin-bottom: 8px; }
.cn-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.cn-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.cn-cm-target.cn-cm-met { background: rgba(56,209,196,0.16); color: #7fe6db; border-color: rgba(56,209,196,0.4); }
.cn-cm-target.cn-cm-missed { background: rgba(255,107,107,0.14); color: #ff9d9d; border-color: rgba(255,107,107,0.36); }
.cn-cm-tick { font-weight: 700; }
.cn-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.cn-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,150,180,0.12); border-radius: 8px; min-width: 96px; }
.cn-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #8296b0; }
.cn-cm-metric strong { font-size: 16px; color: #eaf1f8; }
.cn-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.cn-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(79,155,255,0.10); border-left: 3px solid #4f9bff; border-radius: 4px; color: #d6e3f2; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .cn-cm-metric { min-width: 72px; } .cn-cm-verdict { font-size: 19px; } }


/* Focus visibility + reduced motion (a11y pass 2026-07-28) */
.controlnum-panel select:focus-visible,
.controlnum-panel input:focus-visible,
#nextPeriodBtn:focus-visible,
#undoBtn:focus-visible {
    outline: 2px solid currentColor;
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .controlnum-panel, .controlnum-value, #nextPeriodBtn { transition: none; animation: none; }
}

