(function() {
    'use strict';

    class ControlNumbersAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Control the Numbers`;
            this.version = `1.2.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Nordveld Industrial Supplies B.V.).
            this.START_MARGIN = 6.5;       // operating margin (%)
            this.TARGET_MARGIN = 9.0;      // board target (%)
            this.START_CONGRUENCE = 28;    // goal-congruence score (0–100)
            this.START_CLV = 64;           // retained-customer CLV (€M)
            this.START_LEAK = 6.5;         // annual margin leak from the tail (€M)
            this.CHANGE_BUDGET = 1.2;      // change budget (€M)

            // Concept truths (the modelled best moves).
            this.TRUE_RANK = `costtoserve`;
            this.TRUE_ANCHOR = `custmargin`;
            this.TRUE_PAYBASIS = `balanced`;
            this.TRUE_PORTFOLIO = `segment`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    margin: this.START_MARGIN,         // operating margin (%)
                    congruence: this.START_CONGRUENCE, // goal-congruence score (0–100)
                    clv: this.START_CLV,               // retained-customer CLV (€M)
                    leak: this.START_LEAK,             // annual margin leak still open (€M)
                    budgetLeft: this.CHANGE_BUDGET,    // change budget remaining (€M)
                    budgetSpent: 0,                    // €M committed
                    firedTail: false,                  // exited the whole loss-making tail
                    repFlight: false,                  // top reps walked
                    gameableKpi: false,                // launched a gamed volume KPI
                    metricSprawl: false,               // kept 40+ metrics
                    infoUnfixed: true,                 // slow close + revenue allocation unfixed
                    cosmeticOnly: false,               // margin came from one-off price hikes only
                    marginHistory: [this.START_MARGIN],
                    congruenceHistory: [this.START_CONGRUENCE],
                    clvHistory: [this.START_CLV],
                    leakHistory: [this.START_LEAK],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    rank: `revenue`,
                    drivers: `headcount`,
                    commission: `fine`,
                    depth: 30,
                    focus: `keepall`,
                    anchor: `ordersshipped`,
                    event: `adopt`,
                    info: `later`,
                    gaming: 20,
                    payBasis: `revenue`,
                    transition: `none`,
                    portfolio: `firetail`,
                    repriceEvent: `cave`,
                    budgetSpend: 0,
                    board: `pricepop`,
                    evidence: `assert`,
                    change: `addvolume`,
                    conviction: 50
                };
            }
            this._syncControlsFromDecisions(state);
            this._updateBriefing(state);
        }

        _syncControlsFromDecisions(state) {
            // On resume the framework restores decisions but the DOM still showed the
            // authored defaults, so the player saw values that were not their own.
            const d = state.decisions || {};
            const map = {
                rankInput: d.rank, driversInput: d.drivers, commissionInput: d.commission,
                depthInput: d.depth, focusInput: d.focus, anchorInput: d.anchor,
                eventInput: d.event, infoInput: d.info, gamingInput: d.gaming,
                payBasisInput: d.payBasis, transitionInput: d.transition,
                portfolioInput: d.portfolio, repriceEventInput: d.repriceEvent,
                budgetSpendInput: d.budgetSpend, boardInput: d.board,
                evidenceInput: d.evidence, changeInput: d.change, convictionInput: d.conviction
            };
            Object.keys(map).forEach((id) => {
                if (map[id] === undefined || map[id] === null) return;
                const el = document.getElementById(id);
                if (el) el.value = map[id];
            });
            [[`depthInput`, `depthReadout`], [`gamingInput`, `gamingReadout`]].forEach((pair) => {
                const src = document.getElementById(pair[0]);
                const out = document.getElementById(pair[1]);
                if (src && out) out.textContent = src.value;
            });
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rk = document.getElementById(`rankInput`);
                const dr = document.getElementById(`driversInput`);
                const co = document.getElementById(`commissionInput`);
                const de = document.getElementById(`depthInput`);
                if (rk) decisions.rank = rk.value;
                if (dr) decisions.drivers = dr.value;
                if (co) decisions.commission = co.value;
                if (de) decisions.depth = parseInt(de.value, 10);
                if (!Number.isFinite(decisions.depth) || decisions.depth < 0 || decisions.depth > 100) {
                    warn(`warn_depth_range`); return false;
                }
            } else if (round === 2) {
                const fo = document.getElementById(`focusInput`);
                const an = document.getElementById(`anchorInput`);
                const ev = document.getElementById(`eventInput`);
                const inf = document.getElementById(`infoInput`);
                const ga = document.getElementById(`gamingInput`);
                if (fo) decisions.focus = fo.value;
                if (an) decisions.anchor = an.value;
                if (ev) decisions.event = ev.value;
                if (inf) decisions.info = inf.value;
                if (ga) decisions.gaming = parseInt(ga.value, 10);
                if (!Number.isFinite(decisions.gaming) || decisions.gaming < 0 || decisions.gaming > 100) {
                    warn(`warn_gaming_range`); return false;
                }
            } else if (round === 3) {
                const pb = document.getElementById(`payBasisInput`);
                const tr = document.getElementById(`transitionInput`);
                const po = document.getElementById(`portfolioInput`);
                const re = document.getElementById(`repriceEventInput`);
                const bu = document.getElementById(`budgetSpendInput`);
                if (pb) decisions.payBasis = pb.value;
                if (tr) decisions.transition = tr.value;
                if (po) decisions.portfolio = po.value;
                if (re) decisions.repriceEvent = re.value;
                if (bu) decisions.budgetSpend = parseFloat(bu.value);
                if (!Number.isFinite(decisions.budgetSpend) || decisions.budgetSpend < 0) {
                    warn(`warn_budget_value`); return false;
                }
            } else if (round === 4) {
                const bo = document.getElementById(`boardInput`);
                const ev = document.getElementById(`evidenceInput`);
                const ch = document.getElementById(`changeInput`);
                const cv = document.getElementById(`convictionInput`);
                if (bo) decisions.board = bo.value;
                if (ev) decisions.evidence = ev.value;
                if (ch) decisions.change = ch.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            // Thin wrapper: the round model lives in _computeRound so this method stays
            // short and its return statement is visible to static validators, current and
            // legacy alike. Keep this comment free of apostrophes, quotes and backticks:
            // the older importer treats any of them as a string delimiter and desyncs its
            // brace counter, which produced the false empty-method and missing-return
            // errors on import.
            const r = this._computeRound(state);
            const period = state.currentPeriod;
            return {
                period: period,
                score: r.score,
                overallScore: r.overallScore,
                margin: r.margin,
                marginDelta: r.marginDelta,
                congruence: r.congruence,
                congruenceDelta: r.congruenceDelta,
                clv: r.clv,
                clvDelta: r.clvDelta,
                leak: r.leak,
                budgetLeft: r.budgetLeft,
                firedTail: r.firedTail,
                repFlight: r.repFlight,
                gameableKpi: r.gameableKpi,
                cosmeticOnly: r.cosmeticOnly,
                summary: r.summary,
                coach: r.coach
            };
        }

        _computeRound(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let marginDelta = 0, congruenceDelta = 0, clvDelta = 0, leakDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: load true cost-to-serve, find the whale curve.
                switch (d.rank) {
                    case `costtoserve`: congruenceDelta += 10; leakDelta -= 1.5; coachKey = `coach_r1_costtoserve`; break;
                    case `grossmargin`: congruenceDelta += 1; coachKey = `coach_r1_grossmargin`; break;
                    case `revenue`: congruenceDelta -= 4; leakDelta += 0.5; coachKey = `coach_r1_revenue`; break;
                }

                switch (d.drivers) {
                    case `few`: congruenceDelta += 7; leakDelta -= 1.0; break;
                    case `headcount`: congruenceDelta -= 2; coachKey = `coach_r1_headcount`; break;
                    case `none`: congruenceDelta -= 5; leakDelta += 0.5; coachKey = `coach_r1_nodrivers`; break;
                }

                switch (d.commission) {
                    case `perverse`: congruenceDelta += 8; coachKey = (d.rank === `costtoserve`) ? `coach_r1_sharp` : coachKey; break;
                    case `fine`: congruenceDelta -= 4; coachKey = `coach_r1_payfine`; break;
                    case `unrelated`: congruenceDelta -= 3; break;
                }

                // Depth of the cost-to-serve load = how much of the leak you can actually see.
                const depth = d.depth / 100;
                leakDelta -= 1.5 * depth;
                if (d.depth >= 70) congruenceDelta += 3;
                else if (d.depth <= 15) { congruenceDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r1_shallow`; }

                summaryKey = (d.rank === `costtoserve` && d.drivers === `few` && d.commission === `perverse`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Measure: focus the scorecard, resist the gameable KPI, fix the information system.
                switch (d.focus) {
                    case `scorecard`: congruenceDelta += 11; coachKey = `coach_r2_scorecard`; break;
                    case `keepall`: congruenceDelta -= 6; ds.metricSprawl = true; coachKey = `coach_r2_keepall`; break;
                    case `three`: congruenceDelta -= 1; coachKey = `coach_r2_three`; break;
                }

                switch (d.anchor) {
                    case `custmargin`: congruenceDelta += 9; marginDelta += 0.2; break;
                    case `revenue`: congruenceDelta -= 3; break;
                    case `ordersshipped`: congruenceDelta -= 5; ds.gameableKpi = true; coachKey = `coach_r2_anchororders`; break;
                }

                switch (d.event) {
                    case `reject`: congruenceDelta += 7; break;
                    case `adopt`: congruenceDelta -= 8; leakDelta += 1.0; ds.gameableKpi = true; coachKey = `coach_r2_eventadopt`; break;
                    case `ignore`: congruenceDelta -= 2; coachKey = `coach_r2_eventignore`; break;
                }

                switch (d.info) {
                    case `both`: congruenceDelta += 8; ds.infoUnfixed = false; coachKey = (d.focus === `scorecard` && d.event === `reject`) ? `coach_r2_systems` : coachKey; break;
                    case `closeonly`: congruenceDelta += 2; break;
                    case `later`: congruenceDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_infolate` : coachKey; break;
                }

                // Goodhart stress-testing protects against gaming risk.
                const gaming = d.gaming / 100;
                congruenceDelta += 4 * gaming;
                if (d.gaming <= 15 && (d.anchor === `ordersshipped` || d.event === `adopt`)) {
                    leakDelta += 0.5; if (coachKey === `coach_default`) coachKey = `coach_r2_nostress`;
                }

                summaryKey = (d.focus === `scorecard` && d.anchor === `custmargin` && d.event === `reject`) ? `sum_r2_good` :
                             (ds.gameableKpi ? `sum_r2_gamed` :
                             (d.focus === `keepall` ? `sum_r2_sprawl` : `sum_r2_weak`));
            } else if (round === 3) {
                // Pay & reallocate: re-base incentives and act on the portfolio with CLV.
                switch (d.payBasis) {
                    case `balanced`: congruenceDelta += 12; marginDelta += 0.4; break;
                    case `profitonly`: congruenceDelta += 4; ds.repFlight = true; coachKey = `coach_r3_payonly`; break;
                    case `revenue`: congruenceDelta -= 6; coachKey = `coach_r3_payrevenue`; break;
                }

                switch (d.transition) {
                    case `phased`: congruenceDelta += 6; clvDelta += 4; break;
                    case `none`: congruenceDelta -= 3; ds.repFlight = true; marginDelta -= 0.5; coachKey = (d.payBasis === `profitonly`) ? `coach_r3_overnight` : coachKey; break;
                    case `cut`: congruenceDelta -= 5; ds.repFlight = true; marginDelta -= 0.8; clvDelta -= 4; coachKey = `coach_r3_cut`; break;
                }

                switch (d.portfolio) {
                    case `segment`: marginDelta += 1.4; clvDelta += 8; leakDelta -= 3.0; congruenceDelta += 4; coachKey = (d.payBasis === `balanced` && d.transition === `phased`) ? `coach_r3_segment` : coachKey; break;
                    case `firetail`: marginDelta += 1.8; clvDelta -= 14; leakDelta -= 4.0; ds.firedTail = true; coachKey = `coach_r3_firetail`; break;
                    case `ignore`: marginDelta -= 0.2; leakDelta += 0.5; coachKey = `coach_r3_ignoretail`; break;
                }

                switch (d.repriceEvent) {
                    case `hold`: marginDelta += 0.3; clvDelta += 3; congruenceDelta += 3; break;
                    case `cave`: marginDelta -= 0.6; congruenceDelta -= 5; leakDelta += 1.0; coachKey = (coachKey === `coach_default`) ? `coach_r3_cave` : coachKey; break;
                    case `dump`: clvDelta -= 5; coachKey = (coachKey === `coach_default`) ? `coach_r3_dump` : coachKey; break;
                }

                // Change budget funds retraining, the rep guarantee and the pricing system.
                const spend = Math.min(d.budgetSpend, ds.budgetLeft);
                ds.budgetSpent = Math.round((ds.budgetSpent + spend) * 100) / 100;
                ds.budgetLeft = Math.round((ds.budgetLeft - spend) * 100) / 100;
                if (d.budgetSpend >= 1.0) { congruenceDelta += 5; clvDelta += 3; if (ds.repFlight && d.transition === `phased`) ds.repFlight = false; }
                else if (d.budgetSpend <= 0) { congruenceDelta -= 4; ds.repFlight = (d.transition !== `phased`) ? true : ds.repFlight; if (coachKey === `coach_default`) coachKey = `coach_r3_nobudget`; }

                summaryKey = (d.payBasis === `balanced` && d.transition === `phased` && d.portfolio === `segment`) ? `sum_r3_good` :
                             (ds.firedTail ? `sum_r3_fired` :
                             (ds.repFlight ? `sum_r3_flight` : `sum_r3_weak`));
            } else if (round === 4) {
                // Recover & defend: is the gain structural or cosmetic?
                // Detect a one-quarter sugar-high: margin moved but congruence never did.
                const structuralSoFar = ds.congruence >= 60 && !ds.gameableKpi && !ds.firedTail;

                switch (d.board) {
                    case `structural`: congruenceDelta += 6; marginDelta += 0.3; coachKey = `coach_r4_structural`; break;
                    case `pricepop`: congruenceDelta -= 3; ds.cosmeticOnly = !structuralSoFar; coachKey = `coach_r4_pricepop`; break;
                    case `revenue`: congruenceDelta -= 5; coachKey = `coach_r4_revenue`; break;
                }

                switch (d.evidence) {
                    case `congruence`: congruenceDelta += 8; clvDelta += 3; coachKey = (d.board === `structural`) ? `coach_r4_evidence` : coachKey; break;
                    case `assert`: congruenceDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r4_assert` : coachKey; break;
                    case `deflect`: congruenceDelta -= 6; ds.cosmeticOnly = !structuralSoFar; coachKey = `coach_r4_deflect`; break;
                }

                switch (d.change) {
                    case `refine`: congruenceDelta += 5; break;
                    case `addvolume`: congruenceDelta -= 6; ds.gameableKpi = true; leakDelta += 0.5; coachKey = `coach_r4_addvolume`; break;
                    case `nothing`: congruenceDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_nothing` : coachKey; break;
                }

                if (d.conviction >= 60) { congruenceDelta += 3; marginDelta += 0.2; }
                else if (d.conviction <= 25) { congruenceDelta -= 3; }

                // Cosmetic margin reverses: a one-off pop without behaviour change gives some back.
                if (ds.cosmeticOnly) { marginDelta -= 0.8; clvDelta -= 5; }

                summaryKey = (d.board === `structural` && d.evidence === `congruence` && d.change === `refine`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.margin = Math.max(0, Math.min(15, Math.round((ds.margin + marginDelta) * 100) / 100));
            ds.congruence = Math.max(0, Math.min(100, Math.round(ds.congruence + congruenceDelta)));
            ds.clv = Math.max(0, Math.round((ds.clv + clvDelta) * 10) / 10);
            ds.leak = Math.max(0, Math.round((ds.leak + leakDelta) * 10) / 10);

            // Firing the whole tail under-absorbs fixed cost: cap the durable margin and bleed CLV.
            if (ds.firedTail) {
                ds.margin = Math.min(ds.margin, 8.4);   // a pop, but fixed-cost absorption caps it short of target
            }
            // Rep flight erases the gain: a gamed congruence ceiling.
            if (ds.repFlight) {
                ds.congruence = Math.min(ds.congruence, 55);
                ds.margin = Math.min(ds.margin, 8.0);
            }
            // A gameable KPI keeps the leak from ever fully closing.
            if (ds.gameableKpi) {
                ds.leak = Math.max(ds.leak, 2.5);
            }
            // An unfixed information system caps how high congruence can climb (can't steer in time).
            if (ds.infoUnfixed && round >= 2) {
                ds.congruence = Math.min(ds.congruence, 78);
            }

            ds.marginHistory.push(ds.margin);
            ds.congruenceHistory.push(ds.congruence);
            ds.clvHistory.push(ds.clv);
            ds.leakHistory.push(ds.leak);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                margin: ds.margin,
                marginDelta: Math.round(marginDelta * 100) / 100,
                congruence: ds.congruence,
                congruenceDelta: Math.round(congruenceDelta),
                clv: ds.clv,
                clvDelta: Math.round(clvDelta * 10) / 10,
                leak: ds.leak,
                budgetLeft: ds.budgetLeft,
                firedTail: ds.firedTail,
                repFlight: ds.repFlight,
                gameableKpi: ds.gameableKpi,
                cosmeticOnly: ds.cosmeticOnly,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMargin(v) {
            // Locale-aware one-decimal percent: en "7.4%", es "7,4%".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `%`;
        }

        _fmtEurM(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Number(v);
            const s = (Math.round(n * 10) / 10).toFixed(1).replace(/\.0$/, ``);
            return `€` + (lang === `es` ? s.replace(`.`, `,`) : s) + `M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.controlnum-card-margin`);
                if (card) {
                    card.classList.toggle(`controlnum-margin-loss`, n < self.START_MARGIN - 0.01);
                    card.classList.toggle(`controlnum-margin-target`, n >= self.TARGET_MARGIN - 0.01);
                }
                return self._fmtMargin(n);
            });

            uiManager.bind(`congruenceDisplay`, `domainState.congruence`, (v) => `${Math.round(Number(v))}`);
            uiManager.bind(`clvDisplay`, `domainState.clv`, (v) => self._fmtEurM(Number(v)));

            uiManager.bind(`budgetDisplay`, `domainState.budgetLeft`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.controlnum-card-budget`);
                if (card) card.classList.toggle(`controlnum-budget-empty`, n <= 0.001);
                return self._fmtEurM(n);
            });

            uiManager.bind(`leakDisplay`, `domainState.leak`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.controlnum-leak-bar`);
                if (bar) {
                    bar.classList.toggle(`controlnum-leak-low`, n < 2.5);
                    bar.classList.toggle(`controlnum-leak-mid`, n >= 2.5 && n < 4.5);
                }
                return self._fmtEurM(n);
            });

            // Depth slider readout.
            const de = document.getElementById(`depthInput`);
            const deReadout = document.getElementById(`depthReadout`);
            if (de && deReadout) {
                deReadout.textContent = de.value;
                de.addEventListener(`input`, function() { deReadout.textContent = de.value; });
            }

            // Gaming stress-test slider readout.
            const ga = document.getElementById(`gamingInput`);
            const gaReadout = document.getElementById(`gamingReadout`);
            if (ga && gaReadout) {
                gaReadout.textContent = ga.value;
                ga.addEventListener(`input`, function() { gaReadout.textContent = ga.value; });
            }
        }

        getChartConfig() {
            return {
                controlChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Operating margin (%)`,
                                data: [],
                                borderColor: `#38d1c4`,
                                backgroundColor: `rgba(56,209,196,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#38d1c4`,
                                yAxisID: `yPct`
                            },
                            {
                                label: `Goal-congruence score (0–100)`,
                                data: [],
                                borderColor: `#4f9bff`,
                                backgroundColor: `rgba(79,155,255,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#4f9bff`,
                                yAxisID: `yScore`
                            },
                            {
                                label: `Retained-customer CLV (€M)`,
                                data: [],
                                borderColor: `#b69bff`,
                                backgroundColor: `rgba(182,155,255,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b69bff`,
                                yAxisID: `yScore`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#9fb6cd`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            yPct: {
                                beginAtZero: true, max: 12, position: `left`,
                                ticks: { color: `#5fe3d4` }, grid: { color: `rgba(120,150,180,0.10)` },
                                title: { display: true, text: `Operating margin (%)`, color: `#5fe3d4` }
                            },
                            yScore: {
                                beginAtZero: true, max: 100, position: `right`,
                                ticks: { color: `#8fb0d6` }, grid: { drawOnChartArea: false },
                                title: { display: true, text: `Score (0–100) · CLV (€M)`, color: `#8fb0d6` }
                            },
                            x: {
                                ticks: { color: `#7e96b0` }, grid: { color: `rgba(120,150,180,0.06)` },
                                title: { display: true, text: `Round`, color: `#7e96b0` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = (state && state.domainState) || {};
            const marginH = ds.marginHistory || [];
            const congruenceH = ds.congruenceHistory || [];
            const clvH = ds.clvHistory || [];
            const labels = marginH.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                controlChart: {
                    labels: labels,
                    datasets: [
                        { data: marginH.map((v) => Math.round(v * 100) / 100) },
                        { data: congruenceH.map((v) => Math.round(v)) },
                        { data: clvH.map((v) => Math.round(v * 10) / 10) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (weights 0.32/0.30/0.20/0.18 sum to 1).
            const margin = Math.round(ds.margin * 100) / 100;
            const congruence = Math.round(ds.congruence);
            const clv = Math.round(ds.clv * 10) / 10;
            const leak = Math.round(ds.leak * 10) / 10;
            const marginProgress = Math.max(0, Math.min(100, ((margin - this.START_MARGIN) / (this.TARGET_MARGIN - this.START_MARGIN)) * 100));
            const clvScore = Math.max(0, Math.min(100, (clv / (this.START_CLV * 1.3)) * 100));
            const leakScore = Math.max(0, Math.min(100, (1 - leak / this.START_LEAK) * 100));
            let composite = Math.round(marginProgress * 0.32 + congruence * 0.30 + clvScore * 0.20 + leakScore * 0.18);

            // v1.2.0: align the score with the verdict. Firing the whole tail maximises
            // both congruence and leak closure, so the classic error this simulation
            // exists to teach against scored 87/100 while being labelled a
            // Value-Destroying Cut. The failure states the tiering already treats as
            // disqualifying now cap the composite instead of being invisible to it.
            if (ds.firedTail && clv < this.START_CLV) composite = Math.min(composite, 55);
            if (ds.repFlight) composite = Math.min(composite, 50);
            if (ds.gameableKpi) composite = Math.min(composite, 60);
            if (ds.cosmeticOnly) composite = Math.min(composite, 65);
            return Math.max(0, Math.min(100, composite));
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="cn-cm-target ' + (ok ? 'cn-cm-met' : 'cn-cm-missed') + '">'
                    + '<span class="cn-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.hitTarget, t('tgt_margin'))
                + chip(!!summary.congruent, t('tgt_congruence'))
                + chip(!!summary.clvProtected, t('tgt_clv'))
                + chip(!!summary.leakClosed, t('tgt_leak'));
            const metric = function (label, val) {
                return '<div class="cn-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const marginStr = (typeof this._fmtMargin === 'function' && summary.margin != null) ? this._fmtMargin(summary.margin) : (summary.margin != null ? summary.margin + '%' : '-');
            const clvStr = (typeof this._fmtEurM === 'function' && summary.clv != null) ? this._fmtEurM(summary.clv) : (summary.clv != null ? '€' + summary.clv + 'M' : '-');
            const leakStr = (typeof this._fmtEurM === 'function' && summary.leak != null) ? this._fmtEurM(summary.leak) : (summary.leak != null ? '€' + summary.leak + 'M' : '-');
            const metrics = ''
                + metric(t('kpi_margin'), marginStr)
                + metric(t('kpi_congruence'), (summary.congruence != null ? summary.congruence : '-') + '/100')
                + metric(t('kpi_clv'), clvStr)
                + metric(t('kpi_leak'), leakStr);
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="cn-cm">'
                +   '<div class="cn-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="cn-cm-verdict">' + verdict + '</div>'
                +   '<div class="cn-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="cn-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="cn-cm-targets">' + targets + '</div>'
                +   '<div class="cn-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="cn-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const margin = Math.round(ds.margin * 100) / 100;
            const congruence = Math.round(ds.congruence);
            const clv = Math.round(ds.clv * 10) / 10;
            const leak = Math.round(ds.leak * 10) / 10;

            const hitTarget = margin >= this.TARGET_MARGIN - 0.01;
            const congruent = congruence >= 65;
            const clvProtected = clv >= this.START_CLV;
            const leakClosed = leak <= 2.5;

            // Composite: margin progress toward 9%, congruence, CLV, leak closure.
            // v1.1.0 FIX A - delegated to _composite(ds) so the persisted per-round score and this
            // completion composite are identical by construction (verbatim v1.0.0 formula).
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.firedTail && !congruent) pattern = `firetail`;
            else if (ds.repFlight) pattern = `repflight`;
            else if (ds.gameableKpi) pattern = `gamed`;
            else if (hitTarget && congruent && clvProtected) pattern = `structural`;
            else if (ds.cosmeticOnly) pattern = `cosmetic`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_lost`;
            if (hitTarget && congruent && clvProtected && leakClosed && composite >= 75) perfKey = `grade_working`;
            else if (congruent && clvProtected && !ds.firedTail && composite >= 60) perfKey = `grade_behaviour`;
            else if (ds.firedTail && !clvProtected) perfKey = `grade_valuedestroy`;
            else if (ds.repFlight) perfKey = `grade_repflight`;
            else if (ds.gameableKpi) perfKey = `grade_gamed`;
            else if (composite >= 50) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (pattern === `structural`) insights.push(window.mySimulation.t(`insight_structural`));
            else if (pattern === `firetail`) insights.push(window.mySimulation.t(`insight_firetail`));
            else if (pattern === `repflight`) insights.push(window.mySimulation.t(`insight_repflight`));
            else if (pattern === `gamed`) insights.push(window.mySimulation.t(`insight_gamed`));
            else if (pattern === `cosmetic`) insights.push(window.mySimulation.t(`insight_cosmetic`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.metricSprawl) insights.push(window.mySimulation.t(`insight_sprawl`));
            if (ds.infoUnfixed) insights.push(window.mySimulation.t(`insight_infounfixed`));
            if (!clvProtected) insights.push(window.mySimulation.t(`insight_clv_low`));
            if (!leakClosed) insights.push(window.mySimulation.t(`insight_leak_open`));
            if (hitTarget && !congruent) insights.push(window.mySimulation.t(`insight_margin_no_behaviour`));

            return {
                gradeKey: perfKey,
                score: composite,
                margin: margin,
                congruence: congruence,
                clv: clv,
                leak: leak,
                hitTarget: hitTarget,
                congruent: congruent,
                clvProtected: clvProtected,
                leakClosed: leakClosed,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performanceKey: perfKey,
                performance: performance,
                performanceLabel: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.repFlight) return window.mySimulation.t(`hint_repflight`);
            if (ds.firedTail) return window.mySimulation.t(`hint_firetail`);
            if (ds.gameableKpi) return window.mySimulation.t(`hint_gamed`);
            if (ds.infoUnfixed && state.currentPeriod >= 2) return window.mySimulation.t(`hint_infounfixed`);
            if (ds.congruence < 45 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_congruence`);
            if (ds.margin >= this.TARGET_MARGIN - 0.01 && ds.congruence >= 65 && ds.clv >= this.START_CLV) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.margin`, label: `Margin`, i18nKey: `col_margin`, formatter: (v) => self._fmtMargin(Number(v)) },
                { key: `results.congruence`, label: `Congruence`, i18nKey: `col_congruence`, formatter: (v) => `${Math.round(Number(v))}` },
                { key: `results.clv`, label: `CLV`, i18nKey: `col_clv`, formatter: (v) => self._fmtEurM(Number(v)) },
                { key: `results.leak`, label: `Leak`, i18nKey: `col_leak`, formatter: (v) => self._fmtEurM(Number(v)) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const period = (state && state.currentPeriod) || 1;
            const finished = period > this.ROUNDS.length;
            const idx = Math.min(period - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (!finished && i === idx) ? `block` : `none`;
            }
            const btnRow = document.getElementById(`cnBtnRow`);
            if (btnRow) btnRow.style.display = finished ? `none` : ``;
        }

